<!-- 文件作用：按先行图实现平台管理员控制台，集中真实经营摘要、待办、可选周期交易曲线与独立管理入口。 -->
<template>
  <AppShell title="平台管理" back>
    <view v-if="error" class="error-box" @click="load">{{ error }} · 点击重试</view>
    <EmptyState v-if="state.ready&&state.user?.role!=='admin'" title="仅平台管理员可访问" detail="平台数据、商户配置和管理操作仅向平台管理员开放。" icon="shield"><button class="text-btn" @click="go('/pages/account/login')">切换账号</button></EmptyState>
    <template v-else-if="state.user?.role==='admin'">
      <SubscribeReminder :scenes="['admin_club']" label="接收新俱乐部申请提醒"/><view class="console-metrics"><view class="console-metric"><text class="metric-number">{{ metric('users') }}</text><text class="metric-label">注册用户</text></view><view class="console-metric"><text class="metric-number">{{ metric('orders') }}</text><text class="metric-label">全部订单</text></view><view class="console-metric"><text class="metric-number metric-money">{{ analytics&&!chartLoading&&!chartError?'¥'+money(analytics.summary.gmv_cents):'—' }}</text><text class="metric-label">周期成交额</text></view></view>
      <view class="todo-section"><text class="section-title">待办事项</text><view class="todo-grid"><button v-for="item in todos" :key="item.key" class="todo-item" @click="go(item.route)"><text class="todo-count">{{ metric(item.key) }}</text><text class="todo-label">{{ item.label }}</text></button></view></view>
      <view class="trend-section"><view class="console-section-heading"><text class="section-title">交易额趋势</text><view class="range-tabs"><button v-for="item in periods" :key="item.value" :class="['range-tab',{active:range===item.value}]" @click="chooseRange(item.value)">{{ item.label }}</button></view></view>
        <view v-if="range==='custom'" class="date-range"><picker class="date-picker" mode="date" :value="startDate" :disabled="chartLoading" @change="startDate=$event.detail.value"><view class="date-value">{{ startDate }}<Icon name="bottom" :size="12"/></view></picker><text class="date-separator">至</text><picker class="date-picker" mode="date" :value="endDate" :disabled="chartLoading" @change="endDate=$event.detail.value"><view class="date-value">{{ endDate }}<Icon name="bottom" :size="12"/></view></picker><button class="text-btn apply-period" :disabled="chartLoading" @click="loadChart">应用</button></view>
        <text v-if="chartError" class="chart-error" @click="loadChart">{{ chartError }} · 重试</text><view v-if="chartLoading" class="chart-loading">正在读取该周期交易数据…</view>
        <template v-else-if="analytics"><text class="period-label">{{ analytics.period.start }} — {{ analytics.period.end }} · 上海时间 · 元</text><TradeChart :days="analytics.series" :color="game.primary_color"/><text v-if="!analytics.summary.gmv_cents&&!analytics.summary.refund_cents&&!analytics.summary.paid_order_count&&!analytics.summary.refunded_order_count" class="chart-empty">该周期暂无服务交易</text><view class="trade-summary"><text>支付 {{ analytics.summary.paid_order_count }} 单</text><text>退款 {{ analytics.summary.refunded_order_count }} 单 · ¥{{ money(analytics.summary.refund_cents) }}</text></view><view class="statistics-help"><text class="statistics-note">{{ analytics.dev_mode?'本地模拟数据 · ':'' }}仅统计服务交易</text><button class="text-btn statistics-toggle" @click="showStatistics=!showStatistics">统计口径<Icon :name="showStatistics?'top':'bottom'" :size="12"/></button></view><text v-if="showStatistics" class="statistics-note">{{ analytics.statistics_note }}</text><text v-if="analytics.legacy_untracked_orders" class="statistics-note">{{ analytics.legacy_untracked_orders }} 笔历史订单缺少完整资金时间记录，需核账后补统计。</text></template>
        <text v-else-if="!chartError" class="chart-loading">尚未读取交易数据</text>
      </view>
      <view class="finance-modules"><button class="finance-module-card" @click="go('/pages/manage/finance/index')"><view class="finance-module-copy"><text class="finance-module-title">资金审核</text><text class="finance-module-note">查看订单付款来源与提现占用</text></view><Icon name="arrow" :size="16"/></button><button class="finance-module-card" @click="go('/pages/manage/finance/settings')"><view class="finance-module-copy"><text class="finance-module-title">交易规则</text><text class="finance-module-note">平台抽成与创建俱乐部押金</text></view><Icon name="arrow" :size="16"/></button></view>
      <view class="console-section-heading module-heading"><text class="section-title">管理模块</text></view>
      <view class="module-grid"><button v-for="module in modules" :key="module.route" class="module-card" @click="go(module.route)"><view class="module-icon"><Icon :name="module.icon" :size="21"/></view><text class="module-label">{{ module.label }}</text><Icon name="arrow" :size="13"/></button></view>
    </template>
    <view v-else-if="!error" class="loading-line">正在读取管理员身份…</view>
  </AppShell>
</template>
<script setup lang="ts">
import { ref } from 'vue'
import AppShell from '../../components/AppShell.vue'
import SubscribeReminder from '../../components/SubscribeReminder.vue'
import EmptyState from '../../components/EmptyState.vue'
import Icon from '../../components/Icon.vue'
