const {overview,analytics,loading,chartLoading,error,chartError,range,startDate,endDate,load,loadOverview,loadChart,chooseRange}=useAdminConsole()
const showStatistics=ref(false)
const periods:Array<{value:'7'|'30'|'custom';label:string}>=[{value:'7',label:'7天'},{value:'30',label:'30天'},{value:'custom',label:'自定义'}]
const todos=[{key:'pending_services',label:'服务待审核',route:'/pages/manage/services?status=pending'},{key:'pending_clubs',label:'俱乐部申请',route:'/pages/manage/clubs?status=pending'},{key:'disputed_orders',label:'订单争议',route:'/pages/manage/orders?refund=1'}]
const modules=[{label:'公共信息',icon:'bell',route:'/pages/manage/content/index'},{label:'文章管理',icon:'receipt',route:'/pages/manage/articles/index'},{label:'图文审核',icon:'shield',route:'/pages/manage/moderation'},{label:'用户管理',icon:'user',route:'/pages/manage/users'},{label:'服务审核',icon:'receipt',route:'/pages/manage/services'},{label:'俱乐部管理',icon:'club',route:'/pages/manage/clubs'},{label:'订单与售后',icon:'orders',route:'/pages/manage/orders'},{label:'游戏配置',icon:'game',route:'/pages/manage/games'},{label:'商家转账配置',icon:'wallet',route:'/pages/manage/wallet'},{label:'微信支付',icon:'weixin',route:'/pages/manage/settings?tab=payment'},{label:'协议管理',icon:'receipt',route:'/pages/manage/settings?tab=agreements'},{label:'平台设置',icon:'settings',route:'/pages/manage/platform'},{label:'操作审计',icon:'shield',route:'/pages/manage/audit'},{label:'AI 设置',icon:'settings',route:'/pages/manage/ai'},{label:'发送平台消息',icon:'bell',route:'/pages/manage/messages'},{label:'客服设置',icon:'headphones',route:'/pages/manage/support'},{label:'微信订阅',icon:'bell',route:'/pages/manage/subscriptions'}]
/** 未完成总览读取时展示占位，真实0值保持0，不用假经营数字填充。 */
function metric(key:string):number|string{return overview.value?overview.value[key]||0:'—'}
</script>
